sys_variable_value.value:
(function execute(inputs, outputs) {

    function getAttachmentAsBase64(attachmentSysId) {
        var gsa = new GlideSysAttachment();
        var gr = new GlideRecord('sys_attachment');
        if (!gr.get(attachmentSysId)) {
            return '';
        }
        return gsa.getContentBase64(gr) || '';
    }

    outputs.logo = getAttachmentAsBase64(gs.getProperty('x_konl_visual_card.logo_id'));
    outputs.characters = getAttachmentAsBase64(gs.getProperty('x_konl_visual_card.character'));
    outputs.instruction = gs.getProperty('x_konl_visual_card.instruction');
    outputs.model = gs.getProperty('x_konl_visual_card.model');
    outputs.sanitised_scene = JSON.stringify(inputs.story);

    var util = new x_konl_visual_card.RecognitionCardUtils();
    outputs.references = util.getExampleCardImages(inputs.category);

    gs.info('[CardGen] References JSON: ' + outputs.references);
    gs.info('[CardGen] References length: ' + outputs.references.length);

})(inputs, outputs);

