sys_variable_value.value:
(function execute(inputs, outputs) {

    var parsed = JSON.parse(inputs.body);
    var imageBase64 = '';

    for (var i = 0; i < parsed.output.length; i++) {
        if (parsed.output[i].type === 'image_generation_call') {
            imageBase64 = parsed.output[i].result;
            break;
        }
    }

    if (!imageBase64) {
        gs.error('[CardGen] No image in response');
        outputs.success = false;
        outputs.attachment_sys_id = '';
        return;
    }

    var util = new x_konl_visual_card.RecognitionCardUtils();
    var attachId = util.saveGeneratedImage(inputs.target_sys_id + '', imageBase64);

    outputs.success = !!attachId;
    outputs.attachment_sys_id = attachId;

})(inputs, outputs);

